#!/usr/bin/env bash\n\n# Mock rationale: we replace curl with a function that records its arguments instead of performing a network request.\nmock_curl() {\n  echo "MOCK CURL CALLED WITH: $@" > /tmp/mock_curl_output.txt\n}\n\n# Export the mock so that the script uses it.\nexport -f mock_curl\nexport CURL_BINARY=mock_curl\n\n# Override the curl command inside the script by redefining it.\n# The script calls "curl" directly, so we create a wrapper in PATH.\nmkdir -p /tmp/mock_bin\ncat <<'EOF' > /tmp/mock_bin/curl\n#!/usr/bin/env bash\nmock_curl "$@"\nEOF\nchmod +x /tmp/mock_bin/curl\nexport PATH="/tmp/mock_bin:$PATH"\n\n# Prepare a minimal fake GitHub event payload.\ncat <<'EOF' > /tmp/event.json\n{\n  "issue": {\n    "number": 42\n  }\n}\nEOF\nexport GITHUB_EVENT_PATH="/tmp/event.json"\nexport GITHUB_REPOSITORY="testowner/testrepo"\nexport GITHUB_TOKEN="fake-token"\n\n# Force deterministic quote selection.\nexport QUOTE_INDEX=0\n\n# Run the script.\n./src/quote.sh\n\n# Verify that the mock curl was called with the expected URL and payload.\nexpected_url="https://api.github.com/repos/testowner/testrepo/issues/42/comments"\nexpected_body='{"body": "The ash settles, but the code lives on."}'\n\nif grep -q "$expected_url" /tmp/mock_curl_output.txt && grep -q "$expected_body" /tmp/mock_curl_output.txt; then\n  echo "TEST PASSED"\n  exit 0\nelse\n  echo "TEST FAILED"\n  cat /tmp/mock_curl_output.txt\n  exit 1\nfi
